O=ROOT/'outputs/data_loader_validation_v1';R=ROOT/'reports'
# savej: 이름에 해당하는 세부 처리를 수행하며 반환값과 예외는 아래 구현의 계약을 따릅니다.
# 입력 인수: path, value.
def savej(path,value):
 Path(path).write_text(json.dumps(value,ensure_ascii=False,indent=2,default=lambda v:v.item() if isinstance(v,np.generic) else str(v)),encoding='utf8')
# table: 이름에 해당하는 세부 처리를 수행하며 반환값과 예외는 아래 구현의 계약을 따릅니다.
# 입력 인수: d.
def table(d):
 # val: 이름에 해당하는 세부 처리를 수행하며 반환값과 예외는 아래 구현의 계약을 따릅니다.
 # 입력 인수: v.
 def val(v):return 'NA' if pd.isna(v) else f'{v:.7g}' if isinstance(v,(float,np.floating)) else str(v).replace('|','/')
 return '\n'.join(['| '+' | '.join(d.columns)+' |','| '+' | '.join(['---']*len(d.columns))+' |']+['| '+' | '.join(val(v) for v in row)+' |' for row in d.itertuples(index=False,name=None)])
# main: 명령행 인수를 읽고 본 파일의 처리 흐름을 실행합니다.
def main():
 if (O/'validation.json').exists():raise SystemExit('Preserve completed validation; use a new output version')
 fingerprint=json.loads((O/'manifest_fingerprint.json').read_text());selection=json.loads((O/'manifest_selection.json').read_text());decode=json.loads((O/'decode_summary.json').read_text());smoke=json.loads((O/'sample_shapes.json').read_text())['coverage'];known=json.loads((O/'target_quarantine_smoke.json').read_text());frame=pd.read_csv(fingerprint['selected_manifest'],keep_default_na=False);base=pd.read_csv(fingerprint['base_manifest'],keep_default_na=False);audit=pd.read_csv(O/'per_image_decode_validation.csv');reviews=pd.read_csv(O/'manual_review_evaluation_risks.csv');canonical=pd.read_csv(ROOT/'outputs/windows_preserved_20261111_v1/image_metadata_with_split.csv');classes=json.loads((ROOT/'outputs/spatial_20261111_v7/classes.json').read_text());boxes=pd.read_csv(ROOT/'outputs/spatial_20261111_v7/defect_bboxes.csv')
 expected=boxes.defect_type.map(classes['yolo']);class_errors=boxes[expected.isna()|boxes.class_id.ne(expected)];class_errors.to_csv(O/'source_class_mapping_errors.csv',index=False)
 assert not len(class_errors);assert not len(geometry_errors(frame));groups=group_audit(frame,True)
 # Protect every source artifact, including the two distinct approval ledgers.
 source_hash_checks={k:file_hash(p)==fingerprint[h] for k,p,h in [('final_manifest',fingerprint['selected_manifest'],'manifest_sha256'),('base_manifest',fingerprint['base_manifest'],'base_sha256'),('crop_ledger',fingerprint['crop_ledger'],'crop_ledger_sha256'),('product_gt_ledger',ROOT/'outputs/object_aware_crop_v1/review/human_approved_gt.jsonl','product_gt_ledger_sha256'),('canonical_annotations',ROOT/'outputs/windows_preserved_20261111_v1/image_metadata_with_split.csv','annotation_sha256'),('original_bbox_table',ROOT/'outputs/spatial_20261111_v7/defect_bboxes.csv','bbox_sha256'),('class_map',ROOT/'outputs/spatial_20261111_v7/classes.json','classes_sha256')]};assert all(source_hash_checks.values()),'Sources changed during validation; previous selection cannot be called final'
 source_root=ROOT/'outputs/model_sources_20261112_v1';source_status={}
 for name,key in SOURCE_KEYS.items():
  m=json.loads((source_root/key/'manifest.json').read_text());checks=[]
  for record in m['files']:
   path=source_root/key/'source'/record['path'];checks.append(dict(path=str(path.relative_to(ROOT)),exists=path.exists(),hash_matches=path.exists() and record.get('sha256')==file_hash(path)))
  source_status[name]=dict(repository=m['repo'],commit=m['commit'],files=checks,all_cached_files_match=all(c['hash_matches'] for c in checks),model_runtime='UNVERIFIED_NO_MODEL_FORWARD')
 savej(O/'model_source_integrity.json',source_status)
 testlog=Path('/tmp/loader_complete_pytest_v2.log').read_text();match=re.search(r'(\d+) passed',testlog)
 if not match or ' failed' in testlog or 'ERROR tests/' in testlog:raise RuntimeError('Full pytest did not pass; preserve failures')
 tests=int(match.group(1));warnings=1 if '1 warning' in testlog else 0
 split=frame.groupby('split').agg(images=('image_id','size'),declared_products=('product_id','nunique')).reset_index();split['image_fraction']=split.images/len(frame);split.to_csv(O/'split_summary.csv',index=False)
 canonical.groupby(['category','status']).agg(images=('image_path','size'),declared_products=('product_id','nunique')).reset_index().to_csv(O/'category_status_summary.csv',index=False);canonical.groupby(['view','status','has_mask']).size().rename('images').reset_index().to_csv(O/'view_annotation_coverage.csv',index=False);audit.groupby(['split','status','detection_status']).size().rename('images').reset_index().to_csv(O/'detection_contract_summary.csv',index=False)
 negative_normal=int(((audit.status=='OK')&audit.detection_trainable).sum());positive_supervised=int(audit.detection_status.eq('SUPERVISED_VALID').sum());invalid=int((~audit.detection_trainable).sum());warning_rows=audit[audit.crop_mask_loss.eq(True)];assert len(warning_rows)==43
 # Error code is class ambiguity, not corrupt mask file or a new inferred defect class.
 assert len(pd.read_csv(O/'unresolved_defect_class_conflicts.csv'))==7
 validation=dict(status='LOADER_IMPLEMENTATION_VERIFIED_WITH_QUARANTINED_ANNOTATIONS_AND_UNVERIFIED_MODEL_RUNTIME',implementation_verified=True,all_dataset_targets_clean=False,selected_manifest=fingerprint['selected_manifest'],manifest_sha256=fingerprint['manifest_sha256'],source_hash_checks=source_hash_checks,rows=len(frame),declared_products=len(groups),categories=frame.category.nunique(),views=frame.view.value_counts().to_dict(),duplicate_image_ids=int(frame.image_id.duplicated().sum()),duplicate_paths=int(frame.original_path.duplicated().sum()),invalid_crop_coordinates=0,split_leakage_groups=0,incomplete_five_view_groups=0,full_original_jpg_decodes=decode['full_jpg_decoded'],image_decode_errors=decode['image_errors'],provided_mask_decodes=decode['mask_states'].get('PRESENT_POSITIVE',0)+decode['mask_states'].get('PRESENT_EMPTY',0)+decode['mask_states'].get('INVALID',0),mask_states=decode['mask_states'],mask_file_decode_or_size_errors=decode['mask_states'].get('INVALID',0),bbox_mask_conflict_images=7,class_conflict='fire_hood HS directory /QS filename; canonical UNRESOLVED; no valid class BBox, no class inferred',source_bbox_rows=len(boxes),source_class_mapping_errors=0,labels_canonical='zero-based defect IDs0..7; torchvision adapters+1',detection_trainable_images=negative_normal+positive_supervised,detection_excluded_images=invalid,detection_contract_counts=decode['detection_statuses'],crop_clipped_boxes=decode['crop_clipped_boxes'],crop_removed_boxes=decode['crop_removed_boxes'],partial_mask_loss_images=decode['crop_mask_loss_images'],all_defects_cropped_out_images=decode['all_defects_removed_images'],human_crop_approvals_matched=selection['latest_approved'],changed_crop_coordinate_rows=selection['changed_coordinates'],approved_rectangles=selection['rectangular_crops'],pending_crop_reviews=selection['pending'],unseen_priority_reviews=selection['unseen_priority_cases'],known_test_annotation_assisted_crops=selection['test_annotation_assisted_reviews'],manual_decision_basis_unverified=selection['decision_basis_unverified'],test_evaluation_independence='NOT_GUARANTEED: known annotation-assisted manual decisions189 plus unknown external judgment',real_smoke=smoke,known_target_smoke=known,unit_tests_passed=tests,unit_tests_failed=0,pytest_warnings=warnings,standalone_input_adapters=12,real_adapter_cases=smoke['adapter_cases'],actual_model_integration={name:'UNVERIFIED_NO_MODEL_FORWARD' for name in SPECS},storage_padding='explicit optional; unpad before model; targets stay in valid per-view coordinates',saved_coordinates_modified=0,new_crop_algorithms=0,new_augmentation_policies=0,model_training=False,weights_downloaded=False,paid_api_calls=False,github_push=False,pdf_or_ppt_generated=False,recorded_utc=datetime.now(timezone.utc).isoformat(),environment=dict(python=platform.python_version(),pytorch=torch.__version__,opencv=cv2.__version__,numpy=np.__version__,pandas=pd.__version__,cuda_used=False,device='cpu',uv=subprocess.check_output(['uv','--version'],text=True).strip()),dataset_decode_checks='Actual pixel decodes and SHA checks; not mere existence or header verification')
 savej(O/'validation.json',validation)
 specs=pd.DataFrame([dict(model=k,RGB_BGR=s.color,resize=s.resize,size=s.size,external_normalization=s.normalization,range='0..255' if s.pixel_scale==255 else 'ImageNet-standardized' if s.normalization=='imagenet' else '0..1',bbox=s.boxes_format,normalized_bbox=s.normalized_boxes,label_offset=s.label_offset,internal_resize=s.internal_resize,internal_normalization=s.internal_normalization,source_center_crop=s.source_center_crop,effective_center_crop=False,runtime='UNVERIFIED') for k,s in SPECS.items()]);specs.to_csv(O/'model_input_contracts.csv',index=False)
 fixed=['# 최종 전처리 검증 결과','검증 대상은 수동 검수가 반영된 preprocessing_metadata_reviewed_v1.csv다. 원본 기준 preprocessing_metadata.csv 및 GT 기반 후보 CSV와 구분했다. 전체141050장이 아닌 실제151050행이다. 구현·무결성·입력 변환은 검증했으나 데이터 타깃이 모두 깨끗한 상태나12모델 실제 통합 완료로 판정하지 않는다.','## 1. 최종 CSV 선정',f'선택: {fingerprint["selected_manifest"]}. SHA-256 `{fingerprint["manifest_sha256"]}`. 수정 시각으로 고르지 않고 원본 기준 CSV 해시, 최신 유효 Crop 승인1594개, 좌표·버전·검수자·시각·정책 해시·원본 파일 식별자가 정확히 일치하는지 대조했다. 다른 유효한 반영본이 없었으며 불일치0이었다. 기준 CSV·승인 Ledger를 수정하거나 CSV를 자동 내보내지 않았다.','제품 GT 승인605개 이력/최신600개와 Crop 승인을 구분했다. Crop 원장은1597개 이력, 최신1595개 항목(승인1594·보류1)이다. 우선 검수 목록 중162개는 기록이 없고 보류1개와 함께 원본C로 유지됐다. 사용자 완료 보고를 전체1757개 Crop 승인으로 확대하지 않았다. 좌표가 바뀐 행1587개, 승인했지만 전체 원본을 유지한 행7개다. 제품 GT가 있다는 이유로 미승인 Crop을 반영하지 않았다.','[선정 근거](../outputs/data_loader_validation_v1/manifest_selection.json), [원본 지문](../outputs/data_loader_validation_v1/manifest_fingerprint.json), [승인 대조 오류](../outputs/data_loader_validation_v1/preprocessing_metadata_reviewed_v1_errors.csv).','## 2. 전체 파일·좌표 무결성','JPG151050개를 실제 픽셀로 디코딩하고 원본 SHA·파일 stat·실제 크기를 확인했다. 제공 PNG51329개도 실제로 읽고1024원본 크기와 대조했다. 존재·헤더 확인만 한 결과가 아니다. 경로·ID중복0, 이미지 디코딩 오류0, 마스크 파일 디코딩·크기 오류0, 유효하지 않은 Crop0이다. 원본좌표 XYXY 끝exclusive이며 자동 보정·반올림·좌표 변경은 하지 않았다.','151050행 중 수동 승인된 직사각형1585개는 UI에서 허용된 명시적 예외다. 기존 정사각형 알고리즘을 다시 적용해 좌표를 바꾸지 않았다. C149463개는 올바른 원본 전체 좌표이며 HUMAN_CROP1587개는 승인 좌표와 일치했다.','전수 디코딩은 CPU3스레드·1000행 Parquet152개 체크포인트를 사용했다. 먼저1000장 Smoke를 확인하고 나머지150050장을 이어서 처리했다. 전체 재개 실행에서 약943.85초가 걸렸으며 원본 이미지 배열 전체를 적재하지 않았다. 완료 파티션은 입력·코드·정책 해시가 같을 때 재사용한다.','## 3. 선언 제품 그룹과 Split',table(split),'30개 품목, 선언 제품30210개, C1~C5 각각30210장이다. 모든 선언 제품에서5시점이 있고 중복 시점·그룹 Split 누수0이다. JPEG 바이트 해시가 같은 이미지의 Split 교차도0이다. 기존 product_id와Split을 그대로 사용했고 물리적 제품 동일성이 독립 검증됐다고 주장하지 않는다.','[품목·상태별 통계](../outputs/data_loader_validation_v1/category_status_summary.csv), [시점·마스크 제공](../outputs/data_loader_validation_v1/view_annotation_coverage.csv).','## 4. 주석 상태와 탐지 학습 계약',table(pd.DataFrame([dict(contract=k,images=v) for k,v in decode['detection_statuses'].items()])),f'탐지 학습에 사용할 수 있는 이미지는 {negative_normal+positive_supervised:,}개(정상 Negative{negative_normal:,} +유효 불량{positive_supervised:,})다. 나머지{invalid:,}개는 정상으로 재분류하지 않고 별도 상태로 반환한다. 마스크 미제공 전체99721개 중 정상72840개와NG26881개를 구분한다. PRESENT_EMPTY34개는 원본에 실제 파일이 제공됐지만 양성 픽셀이 없는NG이며 검토 대상이다.','NG+MISSING은 mask=None·MISSING_ANNOTATION, NG+PRESENT_EMPTY는 빈Tensor·EMPTY_NG_REVIEW다. INVALID는 손상·크기불일치 마스크 상태이며 실제0건, 합성 테스트에서 검증했다. Crop으로 결함이 전부 사라지면 원본 NG와PRESENT_POSITIVE를 유지하고 INVALID_TARGET·all_defects_cropped_out을 기록하도록 구현했다. 실제 전부 소실은0장이었다.','## 5. 실제 발견된7개 주석 문제','fire_hood의 HS 디렉터리에 QS 파일명이 들어간7개 이미지가 canonical defect_type=UNRESOLVED였다. 양성 마스크는 유효하지만 검증된 클래스 BBox가 없다. 마스크 손상이나 새로운 Crop 오류가 아니며 HS/QS 중 하나를 추측해 부여하거나 BBox를 새로 저장하지 않았다. Dataset은 INVALID_TARGET·detection_trainable=False로 반환하고 엄격한 detection collate가 학습 입력을 거부한다. 이진 NG 및 위치 마스크 평가 가능 여부와 다중클래스 탐지 타깃 사용 가능 여부를 구분한다.','[7개 원인 목록](../outputs/data_loader_validation_v1/unresolved_defect_class_conflicts.csv), [주석 오류](../outputs/data_loader_validation_v1/annotation_errors.csv), [실제7개 로딩 확인](../outputs/data_loader_validation_v1/target_quarantine_smoke.json).','## 6. Crop 후 결함·BBox 감사','승인된 기존 Crop에서 양성 마스크 일부 손실43장(Train29, Validation10, Test4)을 관측했다. 원래 검수 경고52건은 제품 BBox 손실까지 포함하므로 마스크 손실43과 같은 지표가 아니다. 결함 전부 소실0, BBox 일부Clip43개, 면적0으로 제거된BBox0개다. 클래스ID는 원본0..7을 유지하며60629개 원본 BBox의 defect_type 매핑 오류0이었다.','[43개 마스크 손실](../outputs/data_loader_validation_v1/crop_defect_losses.csv), [완전 소실 목록](../outputs/data_loader_validation_v1/all_defects_cropped_out.csv), [원본 클래스 검사](../outputs/data_loader_validation_v1/source_class_mapping_errors.csv). 좌표를 사후 변경하지 않았다. 일부 손실을 숨기거나 좋은 전처리로 확정하지 않는다.','## 7. 평가 독립성','Test189개 수동 Crop에서 제품 GT/마스크 참조가 기록돼 있다. 자동 Gate가 Test GT로 좌표를 재계산한 것은 아니지만 사람이 정답을 보조해 만든 전처리이므로 평가 독립성을 보장할 수 없다. 전체 수동 승인 중247개는 정답 참조가 기록되지 않았으나 외부에서 정답을 보지 않았다는 증명은 아니다. 기록 가능한 사실과 미확인 판단 근거를 구분했다.','[검수 근거 및 위험](../outputs/data_loader_validation_v1/manual_review_evaluation_risks.csv). Dataset은 manual_annotation_assisted·requires_evaluation_leakage_review를 반환하며 이 위험을 자동으로 숨기거나 Split을 바꾸지 않는다.','## 8. 실제 로딩과 입력 변환',table(pd.DataFrame([dict(metric=k,value=str(v)) for k,v in smoke.items() if k in ['images','products','categories','views','splits','statuses','mask_states','policies','models','adapter_cases','single_view_batch_shape','five_view_batch_shape']])), '실제315장/63제품,30품목,5시점,3Split,정상150·불량165를 로딩했다. 마스크 MISSING194·PRESENT_POSITIVE120·PRESENT_EMPTY1을 포함했다. 실제 A/B 정책 행은 최종 CSV에 없어 NOT_PRESENT로 기록하고 좌표를 만들어 가장하지 않았다. C303장·HUMAN_CROP12장을 검증했다. A/B 라벨의 저장좌표 사용은 합성 데이터에서 확인했다.','12개 Adapter에서 품목별1장씩 총360개 입력 변환을 실제CPU로 실행했다. Single 배치(2,3,256,256), Five 배치(2,5,3,256,256)를 확인했다. Native 탐지 입력의 가변 크기는 명시적 storage padding 후 unpad하여 원래Tensor와타깃이 정확히 복원됨을 실제10시점에서도 확인했다.','## 9. 테스트와 구현 한계',f'전체 pytest {tests} passed, failed0, NumPy 테스트 매개변수 deprecation warning{warnings}개다. 합성 정상·불량·누락/빈/잘못된 마스크, 좌표·Clip·Scale·CXCYWH·Normalized좌표·RGB·classID·5시점 순서·Split·Collate·승인 대조·중복·디코딩 실패·재현성을 검사했다. 모델별 입력 크기와 이중Normalize/CenterCrop 차단도 확인했다.','실제 Smoke에서 YOLO11/RT-DETRv2 Bilinear Tensor Resize가 최대1.000000119를 만들어 범위 검사가 실패했다. Resize의 부동소수점 경계 오차만0..1로 안정화했고 후속 정규화·255스케일을 적용했다. 원본 Crop 좌표를 바꾸지 않았으며 수정 후 실제 Smoke와회귀 테스트가 통과했다.','모델 실제 forward·가중치·학습·성능 비교·증강 정책 개발은 수행하지 않았다. 모델 통합은12개 모두UNVERIFIED다. PatchCore/Dinomaly/INP-Former의 추가CenterCrop은 기본으로 끄고 최종 입력 크기로 Resize하는 별도 manifest-preserving 실험 조건이다. 공식 baseline과 같은 조건이라고 부르지 않는다.','## 10. 결과 파일과 재현 명령','선택·전체실제디코드·Smoke·최종 문서는 scripts/select_final_preprocessing.py, validate_final_preprocessing_decode.py, smoke_test_data_loaders.py, validate_known_loader_cases.py, finalize_data_loader_validation.py를 사용한다. 선택과완료 보고서는 기존 증거를 덮어쓰지 않으며 decode단계만 체크포인트로 재개한다.','[검증 JSON](../outputs/data_loader_validation_v1/validation.json), [실제 Shape](../outputs/data_loader_validation_v1/sample_shapes.json), [전수 행별 감사](../outputs/data_loader_validation_v1/per_image_decode_validation.csv), [탐지 감독 가능 여부](../outputs/data_loader_validation_v1/annotation_contract.csv), [구현 사용법](DATA_LOADER_IMPLEMENTATION.md). PDF/PPT·Crop이미지 생성0, 원본·승인·최종좌표 수정0, 모델학습0, 유료API0, GitHubPush0.']
 fixed=[s.replace('전체141050장이 아닌 실제151050행이다.','실제151050행이다.') for s in fixed];(R/'FINAL_PREPROCESSING_VALIDATION.md').write_text('\n\n'.join(fixed),encoding='utf8')
 impl=['# Real-IAD 공통 데이터 로더 구현','구현 위치는 기존 Python 패키지와 맞춘 mv_analysis/data/다. src/를 새로 만들지 않았으며 모델·Crop 추정·증강 코드를 호출하지 않는다. 최종 CSV의 저장된 좌표만 읽는다.','## 입력 파일과 버전','최종 전처리 CSV에는 좌표·경로·Split만 있고 학습 정답은 별도 canonical image_metadata_with_split.csv, 기존 defect_bboxes.csv 및classes.json에서image_path 기준으로 결합한다. 경로 문자열로 정답을 추정하지 않는다. 기존 단일 CSV Crop용 helper mv_analysis.crop_manifest는 유지했고, 학습용 Dataset은 주석 파일을 명시적으로 사용한다. source_relative_path/category/view/product_id/split이일치하지 않으면 실패한다.','최종 CSV와 모든 입력파일 해시는 outputs/data_loader_validation_v1/manifest_fingerprint.json에 고정했다. Dataset metadata에manifest_sha256·policy_version·policy_sha256을 반환한다. 좌표오류·중복·제품Split누수는 ManifestError로 막고 자동 수정하지 않는다. 미주석·비정상 탐지 타깃은 빈 정상으로 바꾸지 않는다.','## 기본 Single-view 예제','```python\nfrom torch.utils.data import DataLoader\nfrom mv_analysis.data import (ManifestIndex, SingleViewDataset, get_adapter,\n                              single_view_collate)\n\nindex = ManifestIndex(\n    "outputs/adaptive_crop_full_v1/preprocessing_metadata_reviewed_v1.csv",\n    data_root="/path/to/Real-IAD", require_complete=True,\n)\ndataset = SingleViewDataset(index, split="train", task="anomaly",\n                            adapter=get_adapter("PatchCore"))\nloader = DataLoader(dataset, batch_size=4, num_workers=0,\n                    collate_fn=single_view_collate)\nbatch = next(iter(loader))\n# images: (B,3,224,224). Train anomaly defaults to OK only.\n```','Dataset은image float32 CHW, ID·제품·품목·시점·Split·원본OK/NG, 원본(H,W), exclusive Crop XYXY, mask/None, mask_status, boxes/labels, detection_status, detection_trainable, localization_valid, metadata를 반환한다. Native 입력은RGB0..1이며 Adapter를 붙이면 모델별 값 범위·크기로 바뀐다. 정상·불량에 따른 픽셀 전처리 차이는 없다.','## 탐지 학습용 예제','```python\nfrom mv_analysis.data import detection_collate\n\ndataset = SingleViewDataset(\n    index, split="train", task="detection",\n    adapter=get_adapter("Faster R-CNN"), detection_valid_only=True,\n    eligibility="outputs/data_loader_validation_v1/annotation_contract.csv",\n)\nloader = DataLoader(dataset, batch_size=2, num_workers=0,\n                    collate_fn=detection_collate)\nimages, targets = next(iter(loader))\n# RGB float0..1 image list; absolute XYXY and labels1..8.\n# No model forward is performed here.\n```','detection_collate 기본strict=True는MISSING_ANNOTATION/EMPTY_NG_REVIEW/INVALID_TARGET을 거부한다. detection_valid_only는 검증된 현재 Manifest의 eligibility표로 명시적으로 필터한다. 이는 Split재생성이 아니다. 추론·감사에서 미주석 NG도 로딩할 때는strict=False를명시하고 trainable플래그를 유지한다. Default PyTorch collate는None마스크·가변BBox에맞지 않으므로 제공한collate를 사용한다.','원본 defect class는0..7이며TorchvisionFasterR-CNN/RetinaNet에서만+1로1..8을사용한다. 해당모델의8개결함과background head는9classes구성이필요하다. YOLO/RT-DETR/YOLOS/ViTDet는0..7을유지한다. 원본 canonical_labels도보존한다. NG+MISSING은정상Negative가아니고, 빈NG마스크는별도검토상태다.','## Five-view 예제','```python\nfrom mv_analysis.data import FiveViewDataset, five_view_collate\n\nsingle = SingleViewDataset(index, split="validation", task="all",\n                           adapter=get_adapter("EfficientAD-S"))\nfive = FiveViewDataset(single)  # partial views OFF\nloader = DataLoader(five, batch_size=2, num_workers=0,\n                    collate_fn=five_view_collate)\nbatch = next(iter(loader))\n# images: (B,5,3,256,256), C1,C2,C3,C4,C5\n# Each view retains its own target/mask/None.\n```','선언제품은5시점완전성과한Split을검사한다. 시점누락·로딩실패는기본오류다. allow_partial=True는명시적으로요청할때만K개이미지와missing_or_failed_views를반환하며기본Fivecollate는이를거부한다. 같은제품마스크를합치지않는다.','## 가변 크기 모델의5시점 저장 Padding','```python\nfrom functools import partial\nfrom mv_analysis.data import flatten_five_view_batch\n\nsingle = SingleViewDataset(index, split="test", task="all",\n                           adapter=get_adapter("Faster R-CNN"))\nfive = FiveViewDataset(single, pad_storage=True)\nloader = DataLoader(five, batch_size=2,\n                    collate_fn=partial(five_view_collate, pad_storage=True))\nbatch = next(iter(loader))\n# Inference/audit only: invalid per-view supervision remains flagged.\nimages, targets = flatten_five_view_batch(batch, strict_detection=False)\n# Remove storage padding before passing images to a native model.\n```','Padding은배치저장용으로만명시적허용하고BBox·마스크·정규화좌표는각시점의유효(H,W)에그대로둔다. flatten_five_view_batch가원래크기이미지를정확히복원한다. 기본strict_detection=True는미주석/무효시점이탐지훈련Negative로펼쳐지는것도차단한다. 정상모델native입력으로저장패딩을그대로보내면안된다. 이미학습가능시점만필터하면5시점이깨질수있으므로자동으로부분제품을허용하지않는다.','## 12개 입력 Adapter 계약',table(specs[['model','resize','size','external_normalization','range','bbox','normalized_bbox','label_offset']]),'입력공통은RGBfloat32 CHW0..1이다. mask=None은유지하고유효마스크만NEAREST로같은기하변환을적용한다. Bilinear이미지보간은Tensor구현으로align_corners=False, YOLO외antialias=True이며저자PIL/다른버전과비트일치를주장하지않는다. YOLO는640 LetterBox/pad114, RT-DETR는640정사각, YOLOS는짧은변800/긴변1333상한, ViTDet는긴변1024후저장입력1024패딩이다.','FasterR-CNN/RetinaNet은native크기·RGB0..1·외부Normalize없음으로모델내부Resize800/1333및ImageNetNormalize에위임한다. ViTDet은RGB0..255 float32입력브리지이며내부mean/std수치·실제mapperdtype통합은UNVERIFIED다. RT-DETRbackbone내추가정규화도UNVERIFIED다. 12개모델실제통합을실행하지않았다.','PatchCore224, Dinomaly/INP-Former392는저장Crop을보존하기위해공식추가CenterCrop을끄고직접Resize하는실험조건이다. 공식기본256→224/448→392CenterCrop조건과같지않다. center_crop=True는이프로필에서거부한다. Adapter를다시적용하거나이미정규화된Tensor를넣으면거부해이중Normalize를막는다. 모델내부전처리와외부변환을둘다실행하지말아야한다.','소스repo/commit/파일은adapter_contracts.json과model_source_integrity.json에기록했다. 기존 [MODEL_INPUT_REQUIREMENTS.md](MODEL_INPUT_REQUIREMENTS.md)를근거로설정했다. 캐시텍스트와해시확인은실제modelforward검증과다르다. Ultralytics/Detectron2/각저자훈련기용최종batchdictionary연동은UNVERIFIED이며제공되는것은독립입력변환과공통Dataset타깃이다.','## 타깃 기하와 작은 결함','원본BBoxXYXY에서Crop원점을빼고범위Clip한뒤면적0을제거하고원래classID를같은keepmask로유지한다. 모델별Resize·LetterBoxPadding을동일하게적용하고CXCYWH·Normalized변환은마지막Adapter에서수행한다. 원본CSV좌표는변경하지않는다.','mask_status는원본제공상태를유지한다. Crop또는Resize로양성마스크가사라지면별도all_defects_cropped_out/resize_erased_all_positive_mask를기록한다. mask_status를MISSING이나정상으로바꾸지않고image-level NG도유지한다. NN다운샘플은작은결함소실을보장해막을수없으며합성1픽셀사례에서소실을정확히기록하는것을검증했다. 모델검출성능향상을의미하지않는다.','## 실행한 검증과 재현',f'전체pytest {tests}개통과, 실제315장이미지·63제품,12Adapter×30품목=360CPU입력변환,Single/Five배치,실제7개INVALID_TARGET차단을확인했다. 원본151050JPG·51329PNG는별도전수디코딩감사로확인했다. 실제정책A/B와손상마스크는현재최종CSV/데이터에없어실데이터검증완료로꾸미지않고합성테스트로분리했다.','```bash\nuv run --offline pytest -q\n# Completed evidence is protected from overwrite.\nuv run --offline python scripts/validate_final_preprocessing_decode.py\n```','최초단계는select_final_preprocessing.py → validate_final_preprocessing_decode.py --max-batches 1 → 같은명령에서--max-batches제거 → smoke_test_data_loaders.py → validate_known_loader_cases.py → finalize_data_loader_validation.py다. 완료선정·Smoke·최종보고서는보존하고새버전으로재실행한다. Checkpoint는입력·코드해시가같을때만재사용한다. runtime문제·클래스충돌을좌표수정이나정답추정으로덮지않는다.']
 (R/'DATA_LOADER_IMPLEMENTATION.md').write_text('\n\n'.join(impl),encoding='utf8')
 logs=O/'logs';logs.mkdir(exist_ok=True)
 for name in ['loader_manifest_selection.log','loader_decode_smoke.log','loader_decode_full.log','loader_real_smoke.log','loader_real_smoke_recovery.log','loader_known_cases.log','loader_complete_pytest_v2.log']:
  src=Path('/tmp')/name
  if src.exists() and not (logs/name).exists():shutil.copy2(src,logs/name)
 artifacts=[O/'validation.json',O/'sample_shapes.json',O/'manifest_fingerprint.json',R/'FINAL_PREPROCESSING_VALIDATION.md',R/'DATA_LOADER_IMPLEMENTATION.md']
 savej(O/'artifact_index.json',dict(files=[dict(path=str(p.relative_to(ROOT)),bytes=p.stat().st_size,sha256=file_hash(p)) for p in artifacts],code=[dict(path=str(p.relative_to(ROOT)),sha256=file_hash(p)) for p in (ROOT/'mv_analysis/data').glob('*.py')],no_pdf_generated=True))
 print(json.dumps(dict(status=validation['status'],tests_passed=tests,decoded=decode['full_jpg_decoded'],invalid_targets=7,mask_partial_loss=43,model_integrations='UNVERIFIED',reports_written=2),ensure_ascii=False))
if __name__=='__main__':main()
